    },
    {
      "dish_name": "Cold Brew Tonic with Orange Peel",
      "macro_role": "Functional Beverage / Caffeine & Hydration",
      "why_chosen": "Smooth cold brew and tonic give me a clean caffeine kick and bitter citrus notes to beat the post-lunch slump without any refined sugar crash."
    }
  ],
  "pairing_synergy": "The smoky, spiced tandoori chicken and garlic butter prawns deliver massive protein with rich umami and clean heat, balanced out by the crisp, sesame-infused snap peas and edamame. Sipping the cold brew tonic with orange peel cuts through the rich garlic butter and refreshes the palate completely.",
